class BankAccount:
    def __init__(self, account_number, initial_deposit=0.0):
        self.__account_number = account_number
        self.__balance = float(initial_deposit) if initial_deposit > 0 else 0.0

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount
            return True
        return False

    def withdraw(self, amount):
        if 0 < amount <= self.__balance:
            self.__balance -= amount
            return True
        return False

    def get_balance(self):
        return self.__balance

