class Queue:
    def __init__(self):
        self.__items = []

    def enqueue(self, item):
        self.__items.append(item)

    def dequeue(self):
        if self.is_empty():
            raise IndexError('dequeue from empty queue')
        return self.__items.pop(0)

    def peek(self):
        if self.is_empty():
            return None
        return self.__items[0]

    def is_empty(self):
        return len(self.__items) == 0

